import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { catchError, firstValueFrom, of } from 'rxjs';

/** BOUND: a place follows this key. USED_UNBOUND: the glyph is drawn somewhere, but nothing follows THIS key (the places follow another key, or are not adapted). UNUSED: drawn nowhere (never a reason to delete it). */
export type IconUsageStatus = 'BOUND' | 'USED_UNBOUND' | 'UNUSED';
export interface IconUsage { status: IconUsageStatus; refs: number; unboundPlaces: number; drawnElsewhere?: number }

/** generated by tools/icon-usage-report.cjs (guarded by icon-usage.guard.spec.ts) */
@Injectable({ providedIn: 'root' })
export class IconUsageService {
	private readonly http = inject(HttpClient);
	readonly phase = signal<'idle' | 'ready' | 'error'>('idle');
	readonly icons = signal<Record<string, IconUsage>>({});
	private inflight: Promise<void> | null = null;

	load(): Promise<void> {
		if (this.inflight) return this.inflight;
		if (this.phase() === 'ready') return Promise.resolve();
		this.inflight = (async () => {
			const d = await firstValueFrom(this.http.get<{ icons: Record<string, IconUsage>; libraryOnly: Record<string, IconUsage> }>('/assets/site-control/icon-usage.json').pipe(catchError(() => of(null))));
			if (!d?.icons) { this.phase.set('error'); return; }
			this.icons.set({ ...d.libraryOnly, ...d.icons }); this.phase.set('ready');
		})().finally(() => { this.inflight = null; });
		return this.inflight;
	}
	get(id: string): IconUsage | null { return this.icons()[id] ?? null; }
	/** the sentence a not-bound card shows (null when the key is bound or unknown) */
	reason(id: string): string | null {
		const u = this.get(id); if (!u || u.status === 'BOUND') return null;
		return u.status === 'USED_UNBOUND'
			? `مستعملة في الموقع (${u.drawnElsewhere ?? 0} موضعًا برسم مطابق) لكن لا موضع يتبع هذا المفتاح تحديدًا؛ تتبع مفتاحًا آخر.`
			: 'غير مستعملة حاليًا: لا يرسمها أي مكوّن (محفوظة ولا تُحذف).';
	}
}
